def norm(s): return re.sub(r'\s+',' ',str(s or '')).strip()
def rule_for(r):
    lesson=r['lesson']
    if lesson in RULES: return {'rule':RULES[lesson][0],'new_example':RULES[lesson][1],'check':RULES[lesson][2],'basis':'curated_rule_from_platform_topic_and_general_school_knowledge'}
    ideas=r.get('key_ideas') or []
    rule=ideas[0] if ideas else 'استخرج القاعدة من ملاحظة المثال ثم اختبرها على مثال جديد.'
    exq=f"اذكر مثالاً من حياتك الدراسية يوضح الفكرة الآتية: {rule}"
    exa=f"مثال توضيحي: {rule}"
    return {'rule':rule,'new_example':f'سؤال تطبيقي: {exq}\nإجابة نموذجية: {exa}','check':'أعد صياغة القاعدة بكلماتك، ثم تحقق منها بتطبيق مستقل.','basis':'adapted_from_platform_explanation_not_official_text'}

def build(r):
    ideas=[norm(x) for x in r.get('key_ideas',[]) if norm(x)]
    procs=[norm(x) for x in r.get('procedures',[]) if norm(x)]
    targets=[norm(x) for x in r.get('learning_targets',[]) if norm(x)]
    base=ideas[0] if ideas else f'يتناول الدرس مفهوم {r["lesson"]}.'
    rule=rule_for(r)
    examples=[{'kind':'new_guided_example','question':f'طبّق فكرة الدرس على موقف جديد: {r["lesson"]}. ما المعلومة أو الإجراء المناسب؟','answer':rule['new_example'],'reasoning':rule['check'],'steps':(procs[:3] or ['حدد المطلوب في السؤال.','استحضر المفهوم المرتبط بالدرس.','طبق المفهوم وتحقق من النتيجة.'])}]
    remedial=[{'level':'استرجاع','prompt':f'اشرح بكلماتك الفكرة الأساسية: {base}','hint':'استعمل كلمات الدرس، ثم أعط مثالاً قصيراً.','success_criteria':'يذكر المتعلم الفكرة الأساسية دون خلط.'},{'level':'تطبيق موجه','prompt':f'طبّق الدرس في مثال من إنشائك حول «{r["lesson"]}».','hint':'اتبع الخطوات المسجلة للدرس، واذكر سبب اختيارك.','success_criteria':'يطبق المفهوم ويبرر الإجابة.'},{'level':'نقل التعلم','prompt':'أنشئ وضعية قصيرة جديدة تتطلب استعمال الفكرة نفسها، ثم حلها.','hint':'غيّر سياق المثال ولا تكتف بنسخ المثال المحفوظ.','success_criteria':'ينقل التعلم إلى سياق مختلف.'}]
    experiment=None
    if r['lesson'] in EXPERIMENTS and ('علوم' in r['subject'] or 'التربية العلمية' in r['subject']): experiment=EXPERIMENTS[r['lesson']]
    mind={'central_concept':r['lesson'],'branches':[{'label':'الفكرة الأساسية','items':ideas[:4]},{'label':'خطوات العمل','items':procs[:4]},{'label':'هدف التعلم','items':targets[:3]}]}
